first:
réalisation dans $(\mathrm{Ens})$ de syst. de
$(\underbrace{E_n^*}_{\unsure{\mathcal G_n|\mathfrak S_n}\text{-ens.}},{\unsure{\delta|\partial}}_n^*,K_n^*)$
satisfaisant aux relations $(*)$, \uline{plus}

second:
réalisation dans $(\mathrm{Ens})$ de syst.
\unsure{de|des} $(\underbrace{E_n^*}_{\unsure{\mathfrak{S}}_n\text{-ens.}},\partial_n^*,K_n^*)$ \unsure{satisfaisant}
aux relations $(*)$, \uline{plus}

\figure{\begin{tikzpicture}[x=1cm,y=1cm]
\draw (0,0) -- (11.6,0.25) -- (11.6,2.05) -- (0,2.05) -- cycle;
\node at (-0.75,0.95) {$(**)$};
\node (source) at (1.25,1.30) {$E_{p+q}^{*}$};
\node (target) at (4.75,1.30) {$E_p^*\times E_q^*$};
\draw[->] (source.east) -- (target.west);
\node at (8.85,1.45) {surjectif pour};
\node at (8.85,0.65) {$p,q\unsure{\geq}1$};
\end{tikzpicture}}

où $\alpha^*_{n,p}:E_n^*\longrightarrow E_p^*$\quad$(n>p\geq1)$
\uline{défini par}
$\boxed{\alpha_{n,p}^*=\partial_p^*\partial_{p+1}^*\cdots\partial_{n-1}^*}$
\diagram{\begin{tikzcd}[column sep=small]
E_n^* \arrow[r,"\partial_{n-1}^*"] & E_{n-1}^* \arrow[r,"\partial_{\unsure{n-2}}^*"] & E_{n-2}^*\ \cdots \arrow[r,"\partial_p^*"] & E_p^*
\end{tikzcd}}

$\beta_{n,q}^*:E_n^*\longrightarrow E_q^*$\quad$(n\unsure{\geq}q\geq1)$
\uline{défini par}
$\boxed{\beta_{n,q}^*=\partial_q^{\prime *}\partial_{q+1}^{\prime *}\cdots\partial_{n-1}^{\prime *}}$
\diagram{\begin{tikzcd}[column sep=small]
E_n^* \arrow[r,"\partial_{n-1}^{\prime *}"] & E_{n-1}^* \arrow[r,"\partial_{n-2}^{\prime *}"] & E_{n-2}^*\ \cdots \arrow[r,"\partial_q^{\prime *}"] & E_q^*
\end{tikzcd}}
